import re
import json


def read(path):
    try:
        with open(path, "r", errors="replace") as f:
            return f.read()
    except (OSError, ValueError):
        return None


def plist_pairs(block):
    return dict(re.findall(
        r"<key>(.*?)</key>\s*<(?:string|date|integer|real)>(.*?)</(?:string|date|integer|real)>",
        block, re.S))


def os_info():
    info = {}
    text = read("/etc/os-release")
    if text:
        for line in text.splitlines():
            m = re.match(r'^([A-Z_]+)=(.*)$', line)
            if m:
                info[m.group(1)] = m.group(2).strip('"')
    text = read("/System/Library/CoreServices/SystemVersion.plist")
    if text:
        d = plist_pairs(text)
        for k in ("ProductName", "ProductVersion", "ProductBuildVersion"):
            if k in d:
                info[k] = d[k]
    return info


def dpkg_packages():
    text = read("/var/lib/dpkg/status")
    out = []
    if not text:
        return out
    for block in re.split(r"\n\s*\n", text):
        name = re.search(r"^Package:\s*(.+)$", block, re.M)
        ver = re.search(r"^Version:\s*(.+)$", block, re.M)
        st = re.search(r"^Status:\s*(.+)$", block, re.M)
        if name and st and st.group(1).strip().endswith("installed") and "not-installed" not in st.group(1):
            out.append({"name": name.group(1).strip(),
                        "version": ver.group(1).strip() if ver else None})
    return out


def apk_packages():
    text = read("/lib/apk/db/installed")
    out = []
    if not text:
        return out
    for block in re.split(r"\n\s*\n", text):
        name = re.search(r"^P:(.+)$", block, re.M)
        ver = re.search(r"^V:(.+)$", block, re.M)
        if name:
            out.append({"name": name.group(1).strip(),
                        "version": ver.group(1).strip() if ver else None})
    return out


def mac_install_history():
    text = read("/Library/Receipts/InstallHistory.plist")
    out = []
    if not text:
        return out
    for block in re.findall(r"<dict>(.*?)</dict>", text, re.S):
        d = plist_pairs(block)
        if "displayName" in d:
            out.append({
                "name": d.get("displayName"),
                "version": d.get("displayVersion"),
                "date": d.get("date"),
                "installer": d.get("processName"),
            })
    return out


def main():
    report = {
        "os": os_info(),
        "dpkg": dpkg_packages(),
        "apk": apk_packages(),
        "macos_install_history": mac_install_history(),
    }
    report["counts"] = {
        "dpkg": len(report["dpkg"]),
        "apk": len(report["apk"]),
        "macos_install_history": len(report["macos_install_history"]),
    }
    print(json.dumps(report, indent=2, sort_keys=True))


if __name__ == "__main__":
    main()

import re
import json

CONFIG_PATH = "machine_agent_config.json"

DEFAULTS = {
    "agent_name": "machine-agent",
    "check_interval_seconds": 60,
    "log_level": "INFO",
    "enabled_checks": ["disk", "memory", "cpu", "services"],
    "installed": True,
    "version": "1.0.0",
}


def load_existing(path):
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except (FileNotFoundError, ValueError):
        return {}


def validate(cfg):
    if not re.fullmatch(r"[A-Za-z0-9._-]{1,64}", str(cfg["agent_name"])):
        raise ValueError("invalid agent_name")
    if not isinstance(cfg["check_interval_seconds"], int) or cfg["check_interval_seconds"] < 5:
        raise ValueError("invalid check_interval_seconds")
    if not re.fullmatch(r"DEBUG|INFO|WARNING|ERROR", str(cfg["log_level"])):
        raise ValueError("invalid log_level")
    for c in cfg["enabled_checks"]:
        if not re.fullmatch(r"[a-z_]+", str(c)):
            raise ValueError("invalid check name: %r" % (c,))


def main():
    existing = load_existing(CONFIG_PATH)
    cfg = dict(DEFAULTS)
    cfg.update(existing)
    cfg["installed"] = True
    cfg["version"] = DEFAULTS["version"]
    validate(cfg)
    with open(CONFIG_PATH, "w", encoding="utf-8") as f:
        json.dump(cfg, f, indent=2, sort_keys=True)
        f.write("\n")
    print("Installed: wrote %s" % CONFIG_PATH)


if __name__ == "__main__":
    main()

import re
import json

path = input("Registry JSON path: ").strip()
name = input("Package name to uninstall: ").strip()

if not re.fullmatch(r"[A-Za-z0-9._-]+", name):
    print("error: invalid package name")
else:
    try:
        with open(path, "r", encoding="utf-8") as f:
            raw = f.read()
        data = json.loads(raw)
    except (OSError, ValueError) as e:
        print("error: cannot read registry: %s" % e)
        data = None

    if data is not None:
        pkgs = data.get("packages") if isinstance(data, dict) else None
        removed = False
        if isinstance(pkgs, dict) and name in pkgs:
            del pkgs[name]
            removed = True
        elif isinstance(pkgs, list):
            kept = [p for p in pkgs
                    if not (p == name or (isinstance(p, dict) and p.get("name") == name))]
            if len(kept) != len(pkgs):
                data["packages"] = kept
                removed = True

        if not removed:
            print("nothing to do: %s not found in registry" % name)
        else:
            try:
                with open(path + ".bak", "w", encoding="utf-8") as f:
                    f.write(raw)
                with open(path, "w", encoding="utf-8") as f:
                    json.dump(data, f, indent=2)
                    f.write("\n")
                print("uninstalled %s (backup: %s.bak)" % (name, path))
            except OSError as e:
                print("error: cannot write registry: %s" % e)

