import re
import json

NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9@+._/-]*$")


def build_request(raw):
    names = [n for n in re.split(r"[\s,]+", raw.strip()) if n]
    if not names:
        return {"ok": False, "error": "no package names given"}
    bad = [n for n in names if not NAME_RE.match(n) or ".." in n]
    if bad:
        return {"ok": False, "error": "invalid package name(s)", "invalid": bad}
    return {
        "ok": True,
        "action": "exec",
        "changes_world": True,
        "argv": ["brew", "install"] + names,
        "env": {"HOMEBREW_NO_AUTO_UPDATE": "1", "HOMEBREW_NO_ANALYTICS": "1"},
        "verify_argv": ["brew", "list", "--versions"] + names,
    }


def main():
    try:
        raw = input()
    except EOFError:
        raw = ""
    print(json.dumps(build_request(raw)))


main()

import re
import json


def read(path, limit=200000):
    try:
        with open(path, "r", errors="replace") as f:
