def main():
    facts = {}

    osr = read("/etc/os-release")
    if osr:
        d = {}
        for m in re.finditer(r'^(\w+)=(.*)$', osr, re.M):
            d[m.group(1)] = m.group(2).strip().strip('"')
        facts["os_release"] = {k: d[k] for k in ("NAME", "VERSION", "ID", "PRETTY_NAME") if k in d}

    plist = read("/System/Library/CoreServices/SystemVersion.plist")
    if plist:
        mac = {}
        for key in ("ProductName", "ProductVersion", "ProductBuildVersion"):
            m = re.search(r"<key>%s</key>\s*<string>([^<]*)</string>" % key, plist)
            if m:
                mac[key] = m.group(1)
        if mac:
            facts["macos"] = mac

    host = read("/etc/hostname")
    if host:
        facts["hostname"] = host.strip()

    up = read("/proc/uptime")
    if up:
        m = re.match(r"([\d.]+)", up)
        if m:
            facts["uptime_seconds"] = float(m.group(1))

    la = read("/proc/loadavg")
    if la:
        parts = la.split()
        if len(parts) >= 3:
            facts["loadavg"] = [float(x) for x in parts[:3]]

    mem = read("/proc/meminfo")
    if mem:
        mi = {}
        for key in ("MemTotal", "MemFree", "MemAvailable", "SwapTotal", "SwapFree"):
            m = re.search(r"^%s:\s+(\d+)\s*kB" % key, mem, re.M)
            if m:
                mi[key + "_kB"] = int(m.group(1))
        facts["memory"] = mi

    cpu = read("/proc/cpuinfo")
    if cpu:
        facts["cpu_count"] = len(re.findall(r"^processor\s*:", cpu, re.M))
        m = re.search(r"^model name\s*:\s*(.+)$", cpu, re.M)
        if m:
            facts["cpu_model"] = m.group(1).strip()

    res = read("/etc/resolv.conf")
    if res:
        facts["nameservers"] = re.findall(r"^nameserver\s+(\S+)", res, re.M)

    hosts = read("/etc/hosts")
    if hosts:
        facts["hosts_entries"] = len(
            [l for l in hosts.splitlines() if l.strip() and not l.strip().startswith("#")]
        )

    facts["readable_sources"] = sorted(facts.keys())
    print(json.dumps(facts, indent=2, sort_keys=True))


