import re
import json

def read(path):
    try:
        with open(path, "r", errors="replace") as f:
            return f.read()
    except Exception:
        return None

def ipv4(h):
    try:
        b = [int(h[i:i+2], 16) for i in range(0, 8, 2)]
        return ".".join(str(x) for x in reversed(b))
    except Exception:
        return h

def ipv6(h):
    if re.fullmatch(r"0+", h):
        return "::"
    if h == "00000000000000000000000001000000":
        return "::1"
    return h

def tcp_listening(path, v6):
    text = read(path)
    if text is None:
        return None
    out = []
    for line in text.splitlines()[1:]:
        parts = line.split()
        if len(parts) < 4 or parts[3] != "0A":
            continue
        addr, _, port = parts[1].partition(":")
        try:
            p = int(port, 16)
        except ValueError:
            continue
        out.append({"address": ipv6(addr) if v6 else ipv4(addr),
                    "port": p,
                    "proto": "tcp6" if v6 else "tcp"})
    return out

def main():
    report = {"listening": [], "sources": [], "notes": []}

    for path, v6 in (("/proc/net/tcp", False), ("/proc/net/tcp6", True)):
        res = tcp_listening(path, v6)
        if res is not None:
            report["sources"].append(path)
            report["listening"].extend(res)

    if not report["sources"]:
        report["notes"].append("no /proc/net/tcp available; cannot list listening sockets without running external tools")

    report["listening"].sort(key=lambda x: (x["port"], x["proto"], x["address"]))

    host = read("/etc/hostname")
    if host:
        report["hostname"] = host.strip()

    osr = read("/etc/os-release")
    if osr:
        m = re.search(r'^PRETTY_NAME="?([^"\n]+)"?', osr, re.M)
        if m:
            report["os"] = m.group(1)

    plist = read("/System/Library/CoreServices/SystemVersion.plist")
    if plist:
        n = re.search(r"<key>ProductName</key>\s*<string>([^<]*)</string>", plist)
        v = re.search(r"<key>ProductVersion</key>\s*<string>([^<]*)</string>", plist)
        if n and v:
            report["os"] = n.group(1) + " " + v.group(1)

    res = read("/etc/resolv.conf")
    if res:
        report["nameservers"] = re.findall(r"^nameserver\s+(\S+)", res, re.M)

    print(json.dumps(report, indent=2))

main()

import re
import json

def read(path, limit=200000):
    try:
        with open(path, "r", errors="replace") as f:
            return f.read(limit)
    except Exception:
        return None

def kv(text, sep=":"):
    out = {}
    for line in (text or "").splitlines():
        if sep in line:
            k, v = line.split(sep, 1)
            out[k.strip()] = v.strip().strip('"')
    return out

facts = {"readable": {}}

up = read("/proc/uptime")
if up:
    try:
        facts["uptime_seconds"] = float(up.split()[0])
    except Exception:
        pass

la = read("/proc/loadavg")
if la:
    p = la.split()
    if len(p) >= 3:
        facts["loadavg"] = {"1m": p[0], "5m": p[1], "15m": p[2]}
    if len(p) >= 4:
        facts["running_tasks"] = p[3]

mi = read("/proc/meminfo")
if mi:
    m = kv(mi)
    keep = {}
    for k in ("MemTotal", "MemFree", "MemAvailable", "SwapTotal", "SwapFree"):
        if k in m:
            mm = re.match(r"(\d+)", m[k])
            if mm:
                keep[k + "_kB"] = int(mm.group(1))
    facts["memory"] = keep

ci = read("/proc/cpuinfo")
if ci:
    facts["cpu_count"] = len(re.findall(r"^processor\s*:", ci, re.M))
    mn = re.search(r"^model name\s*:\s*(.+)$", ci, re.M)
    if mn:
        facts["cpu_model"] = mn.group(1).strip()

ver = read("/proc/version")
if ver:
    facts["kernel"] = ver.strip()

osr = read("/etc/os-release")
if osr:
    d = kv(osr, "=")
    facts["os"] = d.get("PRETTY_NAME") or d.get("NAME")

hn = read("/proc/sys/kernel/hostname") or read("/etc/hostname")
if hn:
    facts["hostname"] = hn.strip()

nd = read("/proc/net/dev")
if nd:
    ifs = {}
    for line in nd.splitlines()[2:]:
        if ":" in line:
            n, rest = line.split(":", 1)
            f = rest.split()
            if len(f) >= 9:
                ifs[n.strip()] = {"rx_bytes": int(f[0]), "tx_bytes": int(f[8])}
    facts["network"] = ifs

st = read("/proc/self/status")
if st:
    s = kv(st)
    facts["self"] = {"pid": s.get("Pid"), "name": s.get("Name")}

for pth in ("/proc/loadavg", "/proc/meminfo", "/etc/os-release", "/etc/hosts"):
    facts["readable"][pth] = read(pth, 1) is not None

if len(facts) <= 1 or not any(k != "readable" for k in facts):
    facts["note"] = "no /proc data available on this platform"
elif "uptime_seconds" not in facts and "memory" not in facts:
    facts["note"] = "limited information available on this platform"

print(json.dumps(facts, indent=2, sort_keys=True))

def installed(world, M=None, X=None):
    results = []
    seen = set()
    try:
        names = list(world.machines())
    except Exception:
        return []
    if M is not None:
        if M not in names:
            return []
        names = [M]
    for m in names:
        try:
            r = world.run(m, "ollama", "list")
        except Exception:
            continue
        if r.rc != 0:
            continue
        lines = r.out.splitlines()
        for i, line in enumerate(lines):
            line = line.strip()
            if not line:
                continue
            parts = line.split()
            if not parts:
                continue
            if i == 0 and parts[0].upper() == "NAME":
                continue
            model = parts[0]
            if X is not None and model != X:
                continue
            t = (m, model)
            if t not in seen:
                seen.add(t)
                results.append(t)
    return results

import re
import json


def _names(out):
    names = []
    lines = out.splitlines()
    for line in lines[1:]:
        parts = line.split()
        if parts:
            names.append(parts[0])
    return names


def _norm(n):
    n = n.strip()
    last = n.rsplit("/", 1)[-1]
    if ":" not in last:
        n = n + ":latest"
    return n


def _is_installed(world, M, X):
    r = world.run(M, "ollama", "list")
    if r.rc != 0:
        raise RuntimeError("ollama list failed on %s: %s" % (M, (r.err or r.out).strip()))
    target = _norm(X)
    for n in _names(r.out):
        if n == X or _norm(n) == target:
            return True
    return False


def install(world, M, X):
    """Make true: "{X} is installed on {M}"."""
    if not isinstance(M, str) or not isinstance(X, str) or not X.strip():
        raise RuntimeError("invalid machine or model name")
    X = X.strip()
    if M not in world.machines():
        raise RuntimeError("unknown machine: %s" % M)

    if _is_installed(world, M, X):
        return "%s already installed on %s; nothing to do" % (X, M)

    r = world.run(M, "ollama", "pull", X)
    if r.rc != 0:
        raise RuntimeError("ollama pull %s failed on %s (rc=%s): %s"
                           % (X, M, r.rc, (r.err or r.out).strip()))

    if not _is_installed(world, M, X):
        raise RuntimeError("%s not listed on %s after pull" % (X, M))
    return "Pulled %s on %s" % (X, M)

def _names(world, M):
    r = world.run(M, "ollama", "list")
    if r.rc != 0:
        raise RuntimeError("ollama list failed on %s: %s" % (M, (r.err or r.out).strip()))
    names = []
    lines = r.out.splitlines()
    for line in lines[1:]:
        parts = line.split()
        if parts:
            names.append(parts[0])
    return names


def _norm(n):
    n = n.strip()
    if ":" not in n.split("/")[-1]:
        n += ":latest"
    return n


def uninstall(world, M, X):
    """Make true: "{X} is removed from {M}"."""
    if M not in world.machines():
        raise RuntimeError("unknown machine: %s" % M)
    target = _norm(X)
    present = [n for n in _names(world, M) if _norm(n) == target]
    if not present:
        return "%s was not installed on %s; nothing to do" % (X, M)
    r = world.run(M, "ollama", "rm", present[0])
    if r.rc != 0:
        raise RuntimeError("ollama rm %s failed on %s: %s" % (present[0], M, (r.err or r.out).strip()))
    still = [n for n in _names(world, M) if _norm(n) == target]
    if still:
        raise RuntimeError("%s still present on %s after removal" % (X, M))
    return "removed %s from %s" % (present[0], M)

def formulas(world, M=None, P=None):
    try:
        machines = list(world.machines())
    except Exception:
        return []
    if M is not None:
        if M not in machines:
            return []
        machines = [M]
    result = []
    seen = set()
    for m in machines:
        try:
            r = world.run(m, "brew", "list", "-1")
        except RuntimeError:
            continue
        if r.rc != 0:
            continue
        for line in r.out.splitlines():
            line = line.strip()
            if not line or line.startswith("==>"):
                continue
            name = line.split()[0]
            if P is not None and name != P:
                continue
            if (m, name) in seen:
                continue
            seen.add((m, name))
            result.append((m, name))
    return result

def brew_install(world, M, P):
    """Make true: "{P} is a brew package on {M}". Safe to run twice."""
    if not isinstance(P, str) or not P.strip() or P.startswith("-") or any(c.isspace() for c in P):
        raise RuntimeError("invalid package name: %r" % (P,))

    def installed():
        r = world.run(M, "brew", "list", "--formula", "--versions", P)
        return r.rc == 0 and bool(r.out.strip())

    if installed():
        return "%s already installed on %s" % (P, M)

    r = world.run(M, "brew", "install", P)
    if r.rc != 0:
        msg = (r.err or r.out or "").strip()
        raise RuntimeError("brew install %s failed on %s (rc=%d): %s" % (P, M, r.rc, msg))

    if not installed():
        raise RuntimeError("brew install %s reported success on %s but package is not listed" % (P, M))
    return "installed %s on %s" % (P, M)

def setting(world, M=None, K=None, V=None):
    """Return the list of ALL tuples (M, K, V) of str that are true now and agree
    with the arguments that are not None (None means "any": it is a variable).
    Read-only: change nothing. Return [] when nothing matches."""
    import re
    import json

    FACT_PATHS = [
        "/etc/facts.json",
        "/etc/setting.json",
        "/etc/facts",
    ]

    def try_cat(m, path):
        try:
            r = world.run(m, "cat", path)
        except RuntimeError:
            return None
        if r is None or r.rc != 0:
            return None
        return r.out

    def parse_json_facts(text):
        """Expect a JSON object mapping key -> value (str or list of str)."""
        out = []
        try:
            data = json.loads(text)
        except (ValueError, TypeError):
            return out
        if not isinstance(data, dict):
            return out
        for k, v in data.items():
            if isinstance(v, list):
                for item in v:
                    out.append((str(k), str(item)))
            else:
                out.append((str(k), str(v)))
        return out

    def parse_kv_facts(text):
        """Expect lines like key=value or key: value."""
        out = []
        for line in text.splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            m = re.match(r'^([^=:#\s]+)\s*[:=]\s*(.*)$', line)
            if m:
                k, v = m.group(1), m.group(2).strip()
                out.append((k, v))
        return out

    def machine_facts(m):
        facts = []
        for path in FACT_PATHS:
            text = try_cat(m, path)
